import{_ as o,o as d,c as s,a2 as c}from"./chunks/framework.YT-FC_Xx.js";const k=JSON.parse('{"title":"通行证密钥登录（可选）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/passkey.md","filePath":"guide/passkey.md","lastUpdated":1793160153000}'),i={name:"guide/passkey.md"};function t(a,e,n,p,l,r){return d(),s("div",null,[...e[0]||(e[0]=[c('<h1 id="通行证密钥登录-可选" tabindex="-1">通行证密钥登录（可选） <a class="header-anchor" href="#通行证密钥登录-可选" aria-label="Permalink to &quot;通行证密钥登录（可选）&quot;">​</a></h1><p>通行证密钥登录默认关闭，需要管理员在部署环境中主动启用。它不依赖 Cloudflare Turnstile，但用户必须在验证码可用时先用密码登录并绑定密钥；未绑定的账号不能用此功能绕过验证码。原密码登录始终可用。</p><p><strong>新部署与旧版本升级：<strong>新安装生成的 <code>.env</code> 默认没有 <code>FLYX_WEBAUTHN_ORIGIN</code>。升级到支持通行证密钥的版本也</strong>不会自动启用</strong>：安装脚本保留已有 <code>.env</code>，不会向其中添加该变量。如果手动升级时保留了旧版 <code>docker-compose.yml</code>，还需检查 <code>backend.environment</code> 是否包含下文的变量传递项。未设置该变量时，仅更新镜像或版本号后看不到入口是预期行为。</p><ol><li><p>在实际部署目录的 <code>.env</code> 中添加浏览器访问面板时的公开前端 origin，将示例域名换成自己的域名：</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">FLYX_WEBAUTHN_ORIGIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://panel.example.com</span></span></code></pre></div><p>必须使用完整 HTTPS origin（协议、域名、必要时的端口），不能带路径、查询参数或尾部 <code>/</code>。仅本机开发可用 <code>http://localhost:3000</code> 或 <code>http://127.0.0.1:3000</code>。经反向代理访问时仍填浏览器地址栏中的<strong>前端</strong> origin，不填容器地址、后端监听地址或代理转发头；API 即使在另一个域名，也不改变此值。自行部署时将该变量传给 <code>paneld</code> 进程。</p></li><li><p>确认实际使用的 <code>docker-compose.yml</code> 在 <code>backend</code> 服务的 <code>environment</code> 下有以下传递项；新版 Compose 模板已包含，旧模板若缺失需补上：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FLYX_WEBAUTHN_ORIGIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">${FLYX_WEBAUTHN_ORIGIN:-}</span></span></code></pre></div><p>在该部署目录运行 <code>docker compose up -d --force-recreate backend</code>，使新环境变量进入后端容器。后端重建期间，面板 API 会短暂中断。容器恢复后重新加载前端页面；如果 PWA 提示“发现新版本”，选择“刷新”，也可以用新的无痕窗口核对是否仍加载旧页面。</p></li><li><p>用户照常用密码登录，桌面端点右上角“个人资料”，手机端点底部“我的”（均进入 <code>/profile</code>）；在页面顶部的“通行证密钥”卡片输入<strong>当前密码</strong>、可选名称，点击“绑定通行证密钥”并完成设备解锁。新绑定要求设备支持可发现凭据（resident key），不支持的设备会在绑定时失败。绑定或删除均需当前密码，且用户只能管理自己账号的密钥。</p></li><li><p>以后在登录页直接点击“选择通行证密钥登录”，由设备选择账号并解锁，<strong>无需先填写用户名</strong>。账号被停用时密钥登录也会被拒绝。撤销密钥仍到个人资料页输入当前密码并删除。</p><p>旧版本绑定时只“优先”请求可发现凭据，现有密钥是否能直接选账号取决于当时的设备，不能按绑定版本统一判定或批量删除。若设备不显示某把旧密钥，请使用密码登录，在个人资料页删除该密钥并重新绑定；确认新密钥与密码恢复途径可用后再清理其他旧密钥。登录页不提供用户名密钥回退。</p></li></ol><p><strong>入口未显示时，按顺序检查：</strong></p><ol><li>在部署目录运行 <code>docker compose exec backend printenv FLYX_WEBAUTHN_ORIGIN</code>，仅检查这一项是否为预期的公开前端 origin；不要贴出完整 <code>docker compose config</code> 或其他环境变量，以免泄露密码和密钥。若为空，检查 <code>.env</code> 和实际 Compose 模板的 <code>backend.environment</code>，然后按步骤 2 重建后端。</li><li>向浏览器实际调用的后端地址发送公开状态请求，例如将以下示例地址替换为自己的 API 地址后运行 <code>curl -sS -X POST &#39;https://api.example.com/api/v1/user/passkey/status&#39; -H &#39;Content-Type: application/json&#39; -d &#39;{}&#39;</code>。应返回 <code>code: 0</code> 且 <code>data.enabled: true</code>；若为 <code>false</code>，后端尚未接受有效配置。此接口无需登录或提供密码。</li><li>在访问面板的浏览器控制台检查 <code>window.isSecureContext</code> 为 <code>true</code>，且 <code>typeof window.PublicKeyCredential</code> 不是 <code>&quot;undefined&quot;</code>。普通公网 HTTP 页面或不支持 WebAuthn 的浏览器不会显示入口。确认后刷新页面，并查看 <code>/api/v1/user/passkey/status</code> 的实际网络响应。</li><li>若状态已启用且浏览器满足条件，检查 <code>docker compose images frontend</code> 中的前端镜像版本，并按步骤 2 的 PWA 提示刷新或使用无痕窗口。登录页按钮与个人资料页卡片均不存在时，通常是旧前端页面或状态请求未成功；只有其中一个缺失时，记录页面地址和该请求的响应再排查。</li></ol><p>**安全配置与恢复：**未设置或设置错误时，通行证密钥接口拒绝新的绑定和登录，登录页与个人资料页不显示对应入口；密码登录不受影响。不要把不可信的请求 <code>Host</code> / <code>X-Forwarded-Host</code> 当作可信 origin。域名变化会改变 RP ID，旧域名下绑定的密钥不能用于新域名；迁移时需保留原域名或可用的密码登录途径，再在新域名重新绑定。仅更改同一域名的端口也需同步更新此 origin。正在进行的密钥挑战只保存在后端内存中，重启后需重新开始；多副本部署需要共享会话方案，未实现前请保持单个后端实例。</p><p>建议保留至少一种可用的密码恢复途径。数据库级备份会保留密钥记录；当前面板的 JSON 导出不包含通行证密钥，使用 JSON 导入迁移后，用户需要通过密码登录并重新绑定。</p><p>旧的 <code>FLVX_WEBAUTHN_ORIGIN</code> 仍受支持；同时存在时优先使用 <code>FLYX_WEBAUTHN_ORIGIN</code>（显式空值表示停用）。迁移变量名称不需要重新注册密钥，公开 origin 应保持不变。</p>',9)])])}const g=o(i,[["render",t]]);export{k as __pageData,g as default};
